import { html } from "../../../../html.js";
import { useMemo, useState } from "/prototype/vendor/preact-hooks.js";
import { Icon, StatusPill, Dialog } from "../../ui/index.js";
import PageVariants from "../../ui/PageVariants.js";
import { conversations, fmtAgo } from "../../data.js";

const work=conversations.filter(item=>item.kind!=="steward");
const statusLabel={running:"Running",error:"Blocked",held:"Held",done:"Done","waiting-approval":"Needs approval","waiting-followup":"Needs input",interrupted:"Cancelled"};
const bucket=item=>item.status==="running"?"active":item.status==="error"?"blocked":item.status.includes("waiting")||item.status==="held"?"gated":"queued";
const source=item=>item.id==="triage"?"GitHub issue":item.id==="release"?"Schedule":"Webhook";
function Toast({message}){return message&&html`<div class="p-queue-toast" role="status">${message}</div>`}
function Header({title,subtitle,onNew}){return html`<header class="p-queue-head"><div><p class="p-queue-eyebrow">WORK CONTROL</p><h1>${title}</h1><p>${subtitle}</p></div><button class="p-queue-primary" onClick=${onNew}><${Icon} name="plus"/>New work</button></header>`}
function WorkDialog({close,notify}){const [title,setTitle]=useState("");return html`<${Dialog} onClose=${close}><div class="p-queue-dialog"><p class="p-queue-eyebrow">DISPATCH</p><h2>Create work item</h2><label>Objective<input autoFocus value=${title} onInput=${e=>setTitle(e.target.value)} placeholder="What should the fleet do?"/></label><label>Source<select><option>Manual dispatch</option><option>GitHub issue</option><option>Recurring schedule</option></select></label><div class="p-queue-actions"><button onClick=${close}>Cancel</button><button class="p-queue-primary" disabled=${!title.trim()} onClick=${()=>{notify("Work item staged for dispatch");close()}}>Stage work</button></div></div></${Dialog}>`}
function Meta({item}){return html`<div class="p-queue-meta"><span>${item.agent}</span><span>${item.repo}</span><span>${fmtAgo(item.lastActivityAt)}</span></div>`}
function Board({notify}){const [filter,setFilter]=useState("all");const [dialog,setDialog]=useState(false);const items=filter==="all"?work:work.filter(item=>bucket(item)===filter);const lanes=[["queued","Queued"],["active","In flight"],["gated","Awaiting signal"],["blocked","Blocked"]];return html`<main class="e-page p-queue-page"><${Header} title="Work queue" subtitle="Prioritize autonomous work before it becomes operator work." onNew=${()=>setDialog(true)}/><div class="p-queue-toolbar"><div class="p-queue-filter" aria-label="Filter queue">${[["all","All"],["active","Live"],["gated","Gates"],["blocked","Stuck"]].map(([id,label])=>html`<button class=${filter===id?"on":""} onClick=${()=>setFilter(id)}>${label}</button>`)}</div><span class="p-queue-summary"><i></i> 3 agents executing · $4.82 today</span></div><section class="p-queue-board">${lanes.map(([id,label])=>html`<${Lane} id=${id} label=${label} items=${items.filter(item=>bucket(item)===id)} notify=${notify}/>`)} </section>${dialog&&html`<${WorkDialog} close=${()=>setDialog(false)} notify=${notify}/>`}</main>`}
function Lane({id,label,items,notify}){return html`<section class="p-queue-lane"><header><h2>${label}</h2><span>${items.length}</span></header><div class="p-queue-cards">${items.length?items.map(item=>html`<${WorkCard} item=${item} notify=${notify}/>`):html`<div class="p-queue-drop">No work here</div>`}</div></section>`}
function WorkCard({item,notify}){const select=()=>notify(item.title+" selected");const menu=e=>{e.stopPropagation();notify("Actions: retry, hold, cancel")};return html`<article class="p-queue-card" tabindex="0" onClick=${select}><div class="p-queue-card-top"><${StatusPill} status=${statusLabel[item.status]||item.status}/><button aria-label="Item menu" onClick=${menu}>•••</button></div><h3>${item.title}</h3><${Meta} item=${item}/>${item.pr?html`<footer><span>PR #${item.pr}</span><span class=${item.ci==="failing"?"bad":"good"}>${item.ci||"pending"}</span></footer>`:null}</article>`}
function Table({notify}){const [selected,setSelected]=useState(work[0]);const [query,setQuery]=useState("");const [dialog,setDialog]=useState(false);const rows=useMemo(()=>work.filter(item=>item.title.toLowerCase().includes(query.toLowerCase())||item.repo.includes(query)),[query]);return html`<main class="e-page p-queue-page p-queue-table-page"><${Header} title="Operations inbox" subtitle="Exceptions, dependencies, and outcomes across every agent." onNew=${()=>setDialog(true)}/><div class="p-queue-table-layout"><section class="p-queue-table-wrap"><div class="p-queue-table-tools"><input aria-label="Search work" value=${query} onInput=${e=>setQuery(e.target.value)} placeholder="Search work, repo, agent"/><button onClick=${()=>notify("Showing items needing attention")}>Needs attention</button></div><div class="p-queue-table" role="table"><div class="p-queue-tr" role="row"><span>Work item</span><span>State</span><span>Signal</span><span>Updated</span></div>${rows.map(item=>html`<${TableRow} item=${item} selected=${selected.id===item.id} choose=${()=>setSelected(item)}/>`)} </div></section><${Inspector} item=${selected} notify=${notify}/></div>${dialog&&html`<${WorkDialog} close=${()=>setDialog(false)} notify=${notify}/>`}</main>`}
function TableRow({item,selected,choose}){return html`<button class=${selected?"p-queue-tr selected":"p-queue-tr"} onClick=${choose}><span><b>${item.title}</b><small>${source(item)} · ${item.agent}</small></span><span><${StatusPill} status=${statusLabel[item.status]||item.status}/></span><span>${item.pr?"PR #"+item.pr+" · "+(item.ci||"—"):"No PR"}</span><span>${fmtAgo(item.lastActivityAt)}</span></button>`}
function Inspector({item,notify}){const signal=item.status==="error"?"No progress for 31m. Retry with a fresh workspace.":item.gate?"Protected change requires approval.":"Healthy execution path.";return html`<aside class="p-queue-inspector"><div class="p-queue-inspector-title"><span>WORK ITEM</span><button aria-label="Close inspector" onClick=${()=>notify("Inspector pinned")}>⌁</button></div><h2>${item.title}</h2><${StatusPill} status=${statusLabel[item.status]||item.status}/><dl><div><dt>Owner</dt><dd>${item.agent}</dd></div><div><dt>Dependency</dt><dd>${item.parentId||"None"}</dd></div><div><dt>Attempt</dt><dd>${item.unread+1} of 3</dd></div><div><dt>Source</dt><dd>${source(item)}</dd></div></dl><div class="p-queue-signal"><b>Operator signal</b><p>${signal}</p></div><div class="p-queue-actions"><button onClick=${()=>notify("Item placed on hold")}>Hold</button><button class="p-queue-primary" onClick=${()=>notify("Retry queued")}>Retry</button></div></aside>`}
function Timeline({notify}){const [tab,setTab]=useState("Today");const [dialog,setDialog]=useState(false);const scheduled=[["09:00","Dependency sweep","Recurring · platform"],["11:30","Issue triage","GitHub connector · OSS"],["14:00","Release readiness","Manual gate · web"],["17:00","Budget guardrail","Recurring · all organizations"]];return html`<main class="e-page p-queue-page"><${Header} title="Runbook calendar" subtitle="Plan recurring work and intervene before scheduled runs collide." onNew=${()=>setDialog(true)}/><div class="p-queue-calendar-top"><div class="p-queue-filter">${["Today","This week","Recurring"].map(x=>html`<button class=${tab===x?"on":""} onClick=${()=>setTab(x)}>${x}</button>`)}</div><span>Thursday, Oct 24 · local operator time</span></div><section class="p-queue-timeline"><div class="p-queue-time-rail">${scheduled.map(x=>html`<time>${x[0]}</time>`)}</div><div class="p-queue-events">${scheduled.map((event,i)=>html`<article class=${`p-queue-event event-${i}`}><span class="p-queue-event-marker"></span><div><p>${event[2]}</p><h2>${event[1]}</h2><small>${i===1?"12 issues waiting · connector healthy":i===2?"2 PRs blocked by approval":"Next run is ready"}</small></div><button onClick=${()=>notify(`${event[1]} opened`)} aria-label=${`Open ${event[1]}`}><${Icon} name="arrow-up-right"/></button></article>`)}</div><aside class="p-queue-watch"><p class="p-queue-eyebrow">WATCHLIST</p><h2>Preventable stalls</h2><article><b>2 work items share a protected branch gate</b><span>Move one run after approval to avoid duplicate review.</span><button onClick=${()=>notify("Conflict resolution staged")}>Resolve collision</button></article><article><b>Webhook repair has retried once</b><span>It is blocked on a failing fixture, not agent capacity.</span><button onClick=${()=>notify("Retry plan opened")}>Open retry plan</button></article></aside></section>${dialog&&html`<${WorkDialog} close=${()=>setDialog(false)} notify=${notify}/>`}</main>`}
export default function QueuePage(){const [toast,setToast]=useState("");const notify=message=>{setToast(message);setTimeout(()=>setToast(""),2500)};return html`<${PageVariants} variants=${[{key:"1",name:"Board",render:()=>html`<${Board} notify=${notify}/>`},{key:"2",name:"Inbox",render:()=>html`<${Table} notify=${notify}/>`},{key:"3",name:"Runbook",render:()=>html`<${Timeline} notify=${notify}/>`}]}/><${Toast} message=${toast}/>`}
